package com.pharmapack.qms.reconciliation; import com.pharmapack.qms.audit.AuditTrailService; import com.pharmapack.qms.batch.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.math.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/reconciliations") public class ReconciliationController { final ReconciliationRepository rr; final BatchRepository br; final AuditTrailService at; public ReconciliationController(ReconciliationRepository r,BatchRepository b,AuditTrailService a){rr=r;br=b;at=a;}
 @GetMapping public List<ReconciliationResponse> list(){return rr.findAll().stream().map(this::dto).toList();} public record Calc(Long batchId,BigDecimal startingQuantity,BigDecimal goodQuantity,BigDecimal rejectQuantity,BigDecimal unusedQuantity,Long calculatedBy,String remarks){}
 @PostMapping @ResponseStatus(HttpStatus.CREATED) public ReconciliationResponse calculate(@RequestBody Calc x){if(x.startingQuantity()==null||x.startingQuantity().signum()<0)throw new IllegalArgumentException("Starting quantity must be non-negative"); BigDecimal g=n(x.goodQuantity()),r=n(x.rejectQuantity()),u=n(x.unusedQuantity()); BigDecimal rec=g.add(r).add(u),var=x.startingQuantity().subtract(rec); Reconciliation q=rr.findByBatchId(x.batchId()).orElseGet(Reconciliation::new); if(q.getBatch()==null)q.setBatch(br.findById(x.batchId()).orElseThrow(()->new IllegalArgumentException("Batch not found")));q.setStartingQuantity(x.startingQuantity());q.setGoodQuantity(g);q.setRejectQuantity(r);q.setUnusedQuantity(u);q.setReconciledQuantity(rec);q.setVariance(var);q.setStatus(var.compareTo(BigDecimal.ZERO)==0?"RECONCILED":"INVESTIGATION_REQUIRED");q.setCalculatedAt(LocalDateTime.now());q.setCalculatedBy(x.calculatedBy());q.setRemarks(x.remarks());rr.save(q);at.log("CALCULATE","Reconciliation",x.batchId(),"variance",null,var);return dto(rr.findByBatchId(x.batchId()).orElseThrow());}
 ReconciliationResponse dto(Reconciliation q){var b=q.getBatch();return new ReconciliationResponse(q.getId(),b.getId(),b.getBatchNumber(),b.getProduct().getProductCode(),b.getProduct().getProductName(),q.getStartingQuantity(),q.getGoodQuantity(),q.getRejectQuantity(),q.getUnusedQuantity(),q.getReconciledQuantity(),q.getVariance(),q.getStatus(),q.getCalculatedAt(),q.getCalculatedBy(),q.getRemarks());}
 static BigDecimal n(BigDecimal x){return x==null?BigDecimal.ZERO:x;}
}
